insert into private.station_feedback(station_id,success,hints) values('e3000000-0000-4000-8000-000000000003','Runa nickt. „Genau. Die sprechende Runa ist erfunden; Steinkäuze sind echte Eulen.“ Das zweite Steinsiegel, Neugier, glimmt auf eurer Karte.','["Suche die Information aus Wyldos Naturheft.","Die beiden Aussagen über Verwandlung und Schatzkarten gehören zur Fantasie."]'::jsonb) on conflict(station_id) do update set success=excluded.success,hints=excluded.hints;
insert into private.solutions(station_id,accepted) values('e3000000-0000-4000-8000-000000000003',array['eule']) on conflict(station_id) do update set accepted=excluded.accepted;
insert into public.dialogues(id,station_id,event,ordinal,speaker,text,mood) values('e3000000-0000-4000-8000-000000000003-0','e3000000-0000-4000-8000-000000000003','arrival',0,'Runa','In der erfundenen Geschichte landet Runa, der Steinkauz, auf einem Ast. „Eine alte Karte? Dann seid neugierig, aber schaut genau hin“, sagt sie. „Mein Name verrät euch schon etwas über mich.“ Wyldo schlägt sein kleines Naturheft auf: Steinkäuze gehören zu den Eulen.','talk') on conflict(id) do update set text=excluded.text,mood=excluded.mood;
insert into public.stations(id,version_id,ordinal,title,latitude,longitude,radius_m,coordinate_status,seal,content) values('e3000000-0000-4000-8000-000000000004','e2000000-0000-4000-8000-000000000001',4,'Runas leise Botschaft',null,null,40,'unverified','Zuhören','{"title":"Runas leise Botschaft","place":"Vorschlag: ruhiger Abschnitt am Weg","intro":"„Für die nächste Botschaft braucht ihr weder Kopfhörer noch Ton“, erklärt Runa. „Ihr könnt sie hören oder vollständig lesen. Achtet auf die Reihenfolge.“ Wyldo hält seinen Kompass still.","success":"","failure":"Runa wiederholt geduldig die Botschaft. „Zähle die Wörter von vorn; gesucht ist Nummer zwei.“","bridge":"Die Karte zeigt nun vier verstreute Wörter. Gemeinsam müsst ihr daraus eine verständliche Botschaft machen.","id":"e3000000-0000-4000-8000-000000000004","order":4,"point":null,"radius":40,"coordinateStatus":"unverified","seal":"Zuhören","imageAsset":"station-4","dialogues":[{"speaker":"Runa","text":"„Für die nächste Botschaft braucht ihr weder Kopfhörer noch Ton“, erklärt Runa. „Ihr könnt sie hören oder vollständig lesen. Achtet auf die Reihenfolge.“ Wyldo hält seinen Kompass still.","mood":"talk"}],"puzzle":{"kind":"listen","prompt":"Höre die Botschaft oder lies sie unten. Welches Wort nennt Runa als Zweites?","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."],"transcript":"Runa sagt langsam: „Blatt. Wasser. Stein. Wind. Merkt euch das zweite Wort, dann findet ihr das Siegel des Zuhörens.“"}}'::jsonb) on conflict(id) do update set content=excluded.content,title=excluded.title;
insert into public.puzzles(station_id,kind,prompt,options,hints,transcript) values('e3000000-0000-4000-8000-000000000004','listen','Höre die Botschaft oder lies sie unten. Welches Wort nennt Runa als Zweites?','[]'::jsonb,'["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]'::jsonb,'Runa sagt langsam: „Blatt. Wasser. Stein. Wind. Merkt euch das zweite Wort, dann findet ihr das Siegel des Zuhörens.“') on conflict(station_id) do update set kind=excluded.kind,prompt=excluded.prompt,options=excluded.options,hints=excluded.hints,transcript=excluded.transcript;
insert into private.station_feedback(station_id,success,hints) values('e3000000-0000-4000-8000-000000000004','„Wasser“, wiederholt Wyldo. Runa neigt den Kopf. Das dritte Steinsiegel heißt Zuhören. Auch wer die Textalternative gelesen hat, erhält dasselbe Siegel.','["Die Botschaft enthält vier Naturwörter. Zähle ab dem ersten Wort.","Nach „Blatt“ und vor „Stein“ steht das gesuchte Wort."]'::jsonb) on conflict(station_id) do update set success=excluded.success,hints=excluded.hints;
insert into private.solutions(station_id,accepted) values('e3000000-0000-4000-8000-000000000004',array['wasser']) on conflict(station_id) do update set accepted=excluded.accepted;
insert into public.dialogues(id,station_id,event,ordinal,speaker,text,mood) values('e3000000-0000-4000-8000-000000000004-0','e3000000-0000-4000-8000-000000000004','arrival',0,'Runa','„Für die nächste Botschaft braucht ihr weder Kopfhörer noch Ton“, erklärt Runa. „Ihr könnt sie hören oder vollständig lesen. Achtet auf die Reihenfolge.“ Wyldo hält seinen Kompass still.','talk') on conflict(id) do update set text=excluded.text,mood=excluded.mood;
insert into public.stations(id,version_id,ordinal,title,latitude,longitude,radius_m,coordinate_status,seal,content) values('e3000000-0000-4000-8000-000000000005','e2000000-0000-4000-8000-000000000001',5,'Gemeinsam weiter',null,null,40,'unverified','Gemeinschaft','{"title":"Gemeinsam weiter","place":"Vorschlag: breiter Wegabschnitt","intro":"Wyldo legt vier Wortkarten auf dem Bildschirm aus. „Den Schatz finden wir nur zusammen. Setzt unseren Satz in die richtige Reihenfolge.“ Wer allein unterwegs ist, kann sich dabei mit Wyldo und Runa beraten; eine zweite Person ist nicht erforderlich.","success":"","failure":"Die Wörter ergeben noch nicht den Satz auf der Karte. „Fangt mit Gemeinsam an und probiert es noch einmal“, sagt Wyldo.","bridge":"Vier Siegel liegen vor euch. Ihre Reihenfolge wird zum Schlüssel für das nächste Rätsel.","id":"e3000000-0000-4000-8000-000000000005","order":5,"point":null,"radius":40,"coordinateStatus":"unverified","seal":"Gemeinschaft","imageAsset":"station-5","dialogues":[{"speaker":"Wyldo","text":"Wyldo legt vier Wortkarten auf dem Bildschirm aus. „Den Schatz finden wir nur zusammen. Setzt unseren Satz in die richtige Reihenfolge.“ Wer allein unterwegs ist, kann sich dabei mit Wyldo und Runa beraten; eine zweite Person ist nicht erforderlich.","mood":"talk"}],"puzzle":{"kind":"order","prompt":"Tippe die Wortkarten in dieser Reihenfolge an: Gemeinsam kommen wir weiter. Mit „Reihenfolge löschen“ kannst du neu beginnen.","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."],"options":[{"id":"wir","label":"wir"},{"id":"weiter","label":"weiter"},{"id":"gemeinsam","label":"Gemeinsam"},{"id":"kommen","label":"kommen"}]}}'::jsonb) on conflict(id) do update set content=excluded.content,title=excluded.title;
insert into public.puzzles(station_id,kind,prompt,options,hints,transcript) values('e3000000-0000-4000-8000-000000000005','order','Tippe die Wortkarten in dieser Reihenfolge an: Gemeinsam kommen wir weiter. Mit „Reihenfolge löschen“ kannst du neu beginnen.','[{"id":"wir","label":"wir"},{"id":"weiter","label":"weiter"},{"id":"gemeinsam","label":"Gemeinsam"},{"id":"kommen","label":"kommen"}]'::jsonb,'["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]'::jsonb,null) on conflict(station_id) do update set kind=excluded.kind,prompt=excluded.prompt,options=excluded.options,hints=excluded.hints,transcript=excluded.transcript;
insert into private.station_feedback(station_id,success,hints) values('e3000000-0000-4000-8000-000000000005','„Gemeinsam kommen wir weiter!“ Der Satz bringt das vierte Siegel zum Leuchten: Gemeinschaft. Wyldo schaut zu Runa. „Jetzt fehlt uns nur noch der Zugang zum Kristall.“','["Der Satz beginnt mit „Gemeinsam“.","Danach folgen „kommen“, „wir“ und „weiter“."]'::jsonb) on conflict(station_id) do update set success=excluded.success,hints=excluded.hints;
insert into private.solutions(station_id,accepted) values('e3000000-0000-4000-8000-000000000005',array['gemeinsam,kommen,wir,weiter']) on conflict(station_id) do update set accepted=excluded.accepted;
insert into public.dialogues(id,station_id,event,ordinal,speaker,text,mood) values('e3000000-0000-4000-8000-000000000005-0','e3000000-0000-4000-8000-000000000005','arrival',0,'Wyldo','Wyldo legt vier Wortkarten auf dem Bildschirm aus. „Den Schatz finden wir nur zusammen. Setzt unseren Satz in die richtige Reihenfolge.“ Wer allein unterwegs ist, kann sich dabei mit Wyldo und Runa beraten; eine zweite Person ist nicht erforderlich.','talk') on conflict(id) do update set text=excluded.text,mood=excluded.mood;
insert into public.stations(id,version_id,ordinal,title,latitude,longitude,radius_m,coordinate_status,seal,content) values('e3000000-0000-4000-8000-000000000006','e2000000-0000-4000-8000-000000000001',6,'Der Schlüssel aus vier Siegeln',null,null,40,'unverified',null,'{"title":"Der Schlüssel aus vier Siegeln","place":"Vorschlag: Weg in Richtung Ausgangspunkt","intro":"Die Schatzkarte zeigt vier Mulden. Darunter steht: „Nicht die Größe zählt, sondern die Reihenfolge eurer Entdeckungen.“ Auf der Karte trägt Mut die Zahl 2, Neugier die 4, Zuhören die 1 und Gemeinschaft die 3. Das sind erfundene Zeichen des Spiels, keine Inschriften an den Externsteinen.","success":"","failure":"Wyldo vergleicht die Zeichen. „Die Reihenfolge unserer Reise ist der Schlüssel. Schau in deinen Siegelbeutel.“","bridge":"Hinter der digitalen Tür liegt eine letzte Frage: Was darf man von diesem Ort mitnehmen?","id":"e3000000-0000-4000-8000-000000000006","order":6,"point":null,"radius":40,"coordinateStatus":"unverified","seal":null,"imageAsset":"station-6","dialogues":[{"speaker":"Wyldo","text":"Die Schatzkarte zeigt vier Mulden. Darunter steht: „Nicht die Größe zählt, sondern die Reihenfolge eurer Entdeckungen.“ Auf der Karte trägt Mut die Zahl 2, Neugier die 4, Zuhören die 1 und Gemeinschaft die 3. Das sind erfundene Zeichen des Spiels, keine Inschriften an den Externsteinen.","mood":"talk"}],"puzzle":{"kind":"code","prompt":"Setze die vier Zahlen in der Reihenfolge zusammen, in der du die Siegel erhalten hast. Gib den vierstelligen Code ein.","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]}}'::jsonb) on conflict(id) do update set content=excluded.content,title=excluded.title;
insert into public.puzzles(station_id,kind,prompt,options,hints,transcript) values('e3000000-0000-4000-8000-000000000006','code','Setze die vier Zahlen in der Reihenfolge zusammen, in der du die Siegel erhalten hast. Gib den vierstelligen Code ein.','[]'::jsonb,'["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]'::jsonb,null) on conflict(station_id) do update set kind=excluded.kind,prompt=excluded.prompt,options=excluded.options,hints=excluded.hints,transcript=excluded.transcript;
insert into private.station_feedback(station_id,success,hints) values('e3000000-0000-4000-8000-000000000006','Mit 2413 öffnet sich auf dem Bildschirm eine steinerne Tür. Niemand muss eine echte Tür suchen oder einen abgesperrten Bereich betreten.','["Beginne mit Mut und Neugier. Ihre Zahlen sind 2 und 4.","Die ganze Reihenfolge lautet: Mut 2, Neugier 4, Zuhören 1, Gemeinschaft 3."]'::jsonb) on conflict(station_id) do update set success=excluded.success,hints=excluded.hints;
insert into private.solutions(station_id,accepted) values('e3000000-0000-4000-8000-000000000006',array['2413']) on conflict(station_id) do update set accepted=excluded.accepted;
insert into public.dialogues(id,station_id,event,ordinal,speaker,text,mood) values('e3000000-0000-4000-8000-000000000006-0','e3000000-0000-4000-8000-000000000006','arrival',0,'Wyldo','Die Schatzkarte zeigt vier Mulden. Darunter steht: „Nicht die Größe zählt, sondern die Reihenfolge eurer Entdeckungen.“ Auf der Karte trägt Mut die Zahl 2, Neugier die 4, Zuhören die 1 und Gemeinschaft die 3. Das sind erfundene Zeichen des Spiels, keine Inschriften an den Externsteinen.','talk') on conflict(id) do update set text=excluded.text,mood=excluded.mood;
insert into public.stations(id,version_id,ordinal,title,latitude,longitude,radius_m,coordinate_status,seal,content) values('e3000000-0000-4000-8000-000000000007','e2000000-0000-4000-8000-000000000001',7,'Was wir bewahren',null,null,40,'unverified',null,'{"title":"Was wir bewahren","place":"Vorschlag: Rückweg auf ausgeschildertem Weg","intro":"Runa zeigt auf den Wald und die Felsen. „Unser Abenteuer ist erfunden. Dieser Ort und die Menschen, Tiere und Pflanzen hier sind echt. Ein guter Schatzsucher hinterlässt keine Spuren.“ Wyldo faltet die Karte sorgfältig zusammen.","success":"","failure":"„Unser Schatz braucht keine echten Fundstücke“, erinnert Runa. „Bleib auf dem Weg und lass die Natur an ihrem Platz.“","bridge":"Im Finale treffen alle vier Siegel aufeinander. Ihr bleibt an einem sicheren Platz auf dem Weg.","id":"e3000000-0000-4000-8000-000000000007","order":7,"point":null,"radius":40,"coordinateStatus":"unverified","seal":null,"imageAsset":"station-7","dialogues":[{"speaker":"Runa","text":"Runa zeigt auf den Wald und die Felsen. „Unser Abenteuer ist erfunden. Dieser Ort und die Menschen, Tiere und Pflanzen hier sind echt. Ein guter Schatzsucher hinterlässt keine Spuren.“ Wyldo faltet die Karte sorgfältig zusammen.","mood":"talk"}],"puzzle":{"kind":"choice","prompt":"Was gehört in deinen Rucksack, wenn du nach Hause gehst?","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."],"options":[{"id":"erinnerung","label":"Erinnerungen und meinen eigenen Abfall."},{"id":"moos","label":"Moos und ein Stück Fels als Andenken."},{"id":"fund","label":"Ein versteckter Gegenstand, den ich abseits des Weges suche."}]}}'::jsonb) on conflict(id) do update set content=excluded.content,title=excluded.title;
insert into public.puzzles(station_id,kind,prompt,options,hints,transcript) values('e3000000-0000-4000-8000-000000000007','choice','Was gehört in deinen Rucksack, wenn du nach Hause gehst?','[{"id":"erinnerung","label":"Erinnerungen und meinen eigenen Abfall."},{"id":"moos","label":"Moos und ein Stück Fels als Andenken."},{"id":"fund","label":"Ein versteckter Gegenstand, den ich abseits des Weges suche."}]'::jsonb,'["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]'::jsonb,null) on conflict(station_id) do update set kind=excluded.kind,prompt=excluded.prompt,options=excluded.options,hints=excluded.hints,transcript=excluded.transcript;
insert into private.station_feedback(station_id,success,hints) values('e3000000-0000-4000-8000-000000000007','„Erinnerungen und unseren eigenen Abfall“, bestätigt Wyldo. „Der Ort bleibt so, wie wir ihn vorfinden möchten.“ Runa öffnet ihre Flügel: Der Kristall wartet.','["Im Spiel werden ausschließlich digitale Siegel gesammelt.","Lass Naturmaterialien liegen und nimm deinen eigenen Abfall wieder mit."]'::jsonb) on conflict(station_id) do update set success=excluded.success,hints=excluded.hints;
