insert into public.dialogues(id,station_id,event,ordinal,speaker,text,mood) values('e3000000-0000-4000-8000-000000000007-0','e3000000-0000-4000-8000-000000000007','arrival',0,'Runa','Runa zeigt auf den Wald und die Felsen. „Unser Abenteuer ist erfunden. Dieser Ort und die Menschen, Tiere und Pflanzen hier sind echt. Ein guter Schatzsucher hinterlässt keine Spuren.“ Wyldo faltet die Karte sorgfältig zusammen.','talk') on conflict(id) do update set text=excluded.text,mood=excluded.mood;
insert into public.stations(id,version_id,ordinal,title,latitude,longitude,radius_m,coordinate_status,seal,content) values('e3000000-0000-4000-8000-000000000008','e2000000-0000-4000-8000-000000000001',8,'Der verlorene Schatz',null,null,40,'unverified',null,'{"title":"Der verlorene Schatz","place":"Vorschlag: Abschluss nahe dem Ausgangspunkt","intro":"Nur auf eurem Bildschirm öffnen die vier Steinsiegel eine kleine Kammer. In ihrer Mitte schwebt ein geheimnisvoller Kristall. Wyldo staunt. „Die Karte hat uns nicht zu Gold geführt. Der Kristall trägt all die Momente, in denen wir mutig, neugierig und füreinander da waren.“ Runa fragt: „Welche drei Dinge machen diesen Schatz so wertvoll?“","success":"","failure":"Wyldo lächelt. „Denk an unsere gemeinsame Reise. Wie nennen wir solche Erlebnisse?“","bridge":"Die Geschichte endet hier. Macht euch auf einem freigegebenen Weg sicher auf den Rückweg.","id":"e3000000-0000-4000-8000-000000000008","order":8,"point":null,"radius":40,"coordinateStatus":"unverified","seal":null,"imageAsset":"station-8","dialogues":[{"speaker":"Wyldo","text":"Nur auf eurem Bildschirm öffnen die vier Steinsiegel eine kleine Kammer. In ihrer Mitte schwebt ein geheimnisvoller Kristall. Wyldo staunt. „Die Karte hat uns nicht zu Gold geführt. Der Kristall trägt all die Momente, in denen wir mutig, neugierig und füreinander da waren.“ Runa fragt: „Welche drei Dinge machen diesen Schatz so wertvoll?“","mood":"surprise"}],"puzzle":{"kind":"text","prompt":"Vervollständige die Botschaft: Mut, Neugier und gemeinsam erlebte …","hints":["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]}}'::jsonb) on conflict(id) do update set content=excluded.content,title=excluded.title;
insert into public.puzzles(station_id,kind,prompt,options,hints,transcript) values('e3000000-0000-4000-8000-000000000008','text','Vervollständige die Botschaft: Mut, Neugier und gemeinsam erlebte …','[]'::jsonb,'["Dieser Hinweis wird nach Anforderung vom Server geladen.","Dieser Hinweis wird nach Anforderung vom Server geladen."]'::jsonb,null) on conflict(station_id) do update set kind=excluded.kind,prompt=excluded.prompt,options=excluded.options,hints=excluded.hints,transcript=excluded.transcript;
insert into private.station_feedback(station_id,success,hints) values('e3000000-0000-4000-8000-000000000008','Der Kristall erstrahlt. „Abenteuer!“, rufen Wyldo und Runa. Ihr habt alle vier Siegel zusammengebracht und den verlorenen Schatz gefunden.','["Gesucht ist das Wort für besondere Erlebnisse auf einer gemeinsamen Reise.","Der Titel dieses Spiels beschreibt eine Outdoor-Abenteuer-App. Das gesuchte Wort lautet Abenteuer."]'::jsonb) on conflict(station_id) do update set success=excluded.success,hints=excluded.hints;
insert into private.solutions(station_id,accepted) values('e3000000-0000-4000-8000-000000000008',array['abenteuer','abenteuer.']) on conflict(station_id) do update set accepted=excluded.accepted;
insert into public.dialogues(id,station_id,event,ordinal,speaker,text,mood) values('e3000000-0000-4000-8000-000000000008-0','e3000000-0000-4000-8000-000000000008','arrival',0,'Wyldo','Nur auf eurem Bildschirm öffnen die vier Steinsiegel eine kleine Kammer. In ihrer Mitte schwebt ein geheimnisvoller Kristall. Wyldo staunt. „Die Karte hat uns nicht zu Gold geführt. Der Kristall trägt all die Momente, in denen wir mutig, neugierig und füreinander da waren.“ Runa fragt: „Welche drei Dinge machen diesen Schatz so wertvoll?“','surprise') on conflict(id) do update set text=excluded.text,mood=excluded.mood;
